using System;using System.Drawing;using System.Text;namespace Mapping{    /// <summary>    ///     /// </summary>    public class BinDefinition    {        private readonly BinCodeMap _binCodeMap;        /// <summary>        ///         /// </summary>        /// <param name="binCodeMap"></param>        /// <param name="binCode"></param>        /// <param name="binCount"></param>        /// <param name="work"></param>        public BinDefinition(BinCodeMap binCodeMap, ushort binCode, ushort binCount, bool work)            : this(binCodeMap, binCode, binCount, string.Empty, string.Empty, work, Color.Green)        {        }        /// <summary>        ///         /// </summary>        /// <param name="binCodeMap"></param>        /// <param name="binCode"></param>        /// <param name="binCount"></param>        /// <param name="work"></param>        /// <param name="color"></param>        public BinDefinition(BinCodeMap binCodeMap, ushort binCode, ushort binCount, bool work, Color color)            : this(binCodeMap, binCode, binCount, string.Empty, string.Empty, work, color)        {        }        /// <summary>        ///         /// </summary>        /// <param name="binCodeMap"></param>        /// <param name="binCode"></param>        /// <param name="binCount"></param>        /// <param name="binDescription"></param>        /// <param name="binQuality"></param>        /// <param name="work"></param>        /// <param name="color"></param>        public BinDefinition(BinCodeMap binCodeMap, ushort binCode, ushort binCount, string binDescription, string binQuality, bool work, Color color)        {            if (binCodeMap is null)            {                throw new ArgumentNullException(nameof(binCodeMap), "Argument binCodeMap must not been null for BinDefinition.ctor");            }            this._binCodeMap = binCodeMap;            this.BinCode = binCode;            this.BinCount = binCount;            this.BinDescription = binDescription;            this.BinQuality = binQuality;            this.Work = work;            this.Color = color;        }        /// <summary>        /// A bin category, other that the value assigned to        /// NullBin, that may be assigned to a device.        /// It should be represented according to <see cref="BinFormatType"/>.        /// </summary>        public ushort BinCode { get; private set; }        /// <summary>        ///         /// </summary>        public string AsciiBinCode        {            get            {                return this.GetAsciiBinCode(this._binCodeMap.BinType, this.BinCode);            }        }        /// <summary>        /// The number of devices on the substrate with the specified BinCode.        /// </summary>        public int BinCount { get; internal set; }        /// <summary>        /// A description of the specified BinCode (e.g., "100MHz").        /// </summary>        public string BinDescription { get; private set; }        /// <summary>        /// Describes the quality of the specified BinCode.        /// The following values are reserved:        /// <list type="bullet">        /// <item>"Pass" - Indicates a quality that has commercial value</item>        /// <item>"Fail" - Indicates a quality that does not have commercial value</item>        /// </list>        /// </summary>        public string BinQuality { get; private set; }        /// <summary>        /// Bin color.        /// </summary>        public Color Color { get; internal set; }        /// <summary>        /// Indicates that devices which this BinCode should be processed or not.        /// <list type="bullet">        /// <item>True - indicates that devices whith this BinCode should be processed.</item>        /// <item>False - indicates that devices whith this BinCode should not be processed.</item>        /// </list>        /// </summary>        public bool Work { get; internal set; }        /// <summary>        ///         /// </summary>        /// <param name="obj"></param>        /// <returns></returns>        public override bool Equals(object obj)        {            return this.Equals(obj as BinDefinition);        }        /// <summary>        ///         /// </summary>        /// <param name="obj"></param>        /// <returns></returns>        public bool Equals(BinDefinition obj)        {            if ((obj as object) == null)            {                return false;            }            bool equal = (this.BinCode == obj.BinCode);            return equal;        }        /// <summary>        ///         /// </summary>        /// <returns></returns>        public override int GetHashCode()        {            return this.BinCode;        }        /// <summary>        ///         /// </summary>        /// <returns></returns>        public override string ToString()        {            StringBuilder sb = new StringBuilder(this.AsciiBinCode);            if (!string.IsNullOrEmpty(this.BinDescription))            {                sb.Append($" - {this.BinDescription}");            }            return sb.ToString();        }        /// <summary>        ///         /// </summary>        /// <param name="left"></param>        /// <param name="right"></param>        /// <returns></returns>        public static bool operator ==(BinDefinition left, BinDefinition right)        {            if ((left as object) == null)            {                return ((right as object) == null);            }            return left.Equals(right);        }        /// <summary>        ///         /// </summary>        /// <param name="left"></param>        /// <param name="right"></param>        /// <returns></returns>        public static bool operator !=(BinDefinition left, BinDefinition right)        {            return !(left == right);        }        /// <summary>        ///         /// </summary>        /// <param name="left"></param>        /// <param name="binCode"></param>        /// <returns></returns>        public static bool operator ==(BinDefinition left, ushort binCode)        {            return left.BinCode == binCode;        }        /// <summary>        ///         /// </summary>        /// <param name="left"></param>        /// <param name="binCode"></param>        /// <returns></returns>        public static bool operator !=(BinDefinition left, ushort binCode)        {            return left.BinCode != binCode;        }        /// <summary>        ///         /// </summary>        /// <param name="binCode"></param>        /// <param name="right"></param>        /// <returns></returns>        public static bool operator ==(ushort binCode, BinDefinition right)        {            return binCode == right.BinCode;        }        /// <summary>        ///         /// </summary>        /// <param name="binCode"></param>        /// <param name="right"></param>        /// <returns></returns>        public static bool operator !=(ushort binCode, BinDefinition right)        {            return binCode != right.BinCode;        }        /// <summary>        ///         /// </summary>        /// <param name="left"></param>        /// <param name="binCode"></param>        /// <returns></returns>        public static bool operator ==(BinDefinition left, char binCode)        {            return left.BinCode == binCode;        }        /// <summary>        ///         /// </summary>        /// <param name="left"></param>        /// <param name="binCode"></param>        /// <returns></returns>        public static bool operator !=(BinDefinition left, char binCode)        {            return left.BinCode != binCode;        }        /// <summary>        ///         /// </summary>        /// <param name="binCode"></param>        /// <param name="right"></param>        /// <returns></returns>        public static bool operator ==(char binCode, BinDefinition right)        {            return binCode == right.BinCode;        }        /// <summary>        ///         /// </summary>        /// <param name="binCode"></param>        /// <param name="right"></param>        /// <returns></returns>        public static bool operator !=(char binCode, BinDefinition right)        {            return binCode != right.BinCode;        }        private string GetAsciiBinCode(BinCodeType binCodeType, ushort binCode)        {            string formattedCode = string.Empty;            switch (binCodeType)            {                case BinCodeType.Ascii:                    formattedCode = ((char)binCode).ToString();                    break;                case BinCodeType.Decimal:                    formattedCode = binCode.ToString("000");                    break;                case BinCodeType.HexaDecimal:                    formattedCode = binCode.ToString("X2");                    break;                case BinCodeType.Integer2:                    formattedCode = binCode.ToString("X4");                    break;                default:                    break;            }            return formattedCode;        }    }}